-- Read-only review UI RPCs: identity, tenant isolation, filters, paging and revocation.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select extensions.no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000001','ui-fixture-1@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 1","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000002','ui-fixture-2@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 2","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000003','ui-fixture-3@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 3","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000004','ui-fixture-4@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 4","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000005','ui-fixture-5@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 5","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000006','ui-fixture-6@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 6","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000007','ui-fixture-7@securedesk.example.invalid',now(),'{"full_name":"UI Fixture 7","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('b1000000-0000-4000-8000-000000000008','ui-fixture-8@securedesk.example.invalid',null,'{"full_name":"UI Fixture 8","phone":"+12025550100","company_name":"UI Fictional Company","message":"UI fixture message"}');
update public.profiles set app_role='super_admin',account_status='active' where id='b1000000-0000-4000-8000-000000000001';
update public.profiles set app_role='admin',account_status='active' where id='b1000000-0000-4000-8000-000000000002';
update public.profiles set app_role='staff',account_status='active' where id='b1000000-0000-4000-8000-000000000003';
insert into public.organizations(id,name,description,address,email,phone,status) values('b2000000-0000-4000-8000-000000000001','UI Company 1','Verified fixture details','UI address 1','ui-company-1@securedesk.example.invalid','+12025550100','active');
insert into public.organizations(id,name,description,address,email,phone,status) values('b2000000-0000-4000-8000-000000000002','UI Company 2','Verified fixture details','UI address 2','ui-company-2@securedesk.example.invalid','+12025550100','pending');
insert into public.organizations(id,name,description,address,email,phone,status) values('b2000000-0000-4000-8000-000000000003','UI Company 3','Verified fixture details','UI address 3','ui-company-3@securedesk.example.invalid','+12025550100','active');
insert into public.organizations(id,name,description,address,email,phone,status) values('b2000000-0000-4000-8000-000000000004','UI Company 4','Verified fixture details','UI address 4','ui-company-4@securedesk.example.invalid','+12025550100','inactive');
insert into public.organization_admin_assignments(organization_id,admin_user_id,assigned_by) values('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000001'),('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000001');
update public.registration_requests set target_organization_id='b2000000-0000-4000-8000-000000000001' where user_id='b1000000-0000-4000-8000-000000000004';
update public.registration_requests set target_organization_id='b2000000-0000-4000-8000-000000000002' where user_id='b1000000-0000-4000-8000-000000000005';
update public.registration_requests set target_organization_id='b2000000-0000-4000-8000-000000000003' where user_id='b1000000-0000-4000-8000-000000000006';
update public.registration_requests set target_organization_id='b2000000-0000-4000-8000-000000000002' where user_id='b1000000-0000-4000-8000-000000000008';
-- Compute the fixture's global pending page without assuming an empty saved database.
create temporary table ui_queue_position as
select (select count(*)::integer from public.registration_requests earlier
  where earlier.status='pending' and (earlier.created_at<fixture.created_at
    or (earlier.created_at=fixture.created_at and earlier.id<fixture.id))) as page_offset
from public.registration_requests fixture where fixture.user_id='b1000000-0000-4000-8000-000000000007';
grant select on pg_temp.ui_queue_position to authenticated;
reset role;set local role anon;
select extensions.throws_ok($check$select * from public.current_account_role()$check$,'42501',null::text,'anon cannot execute current_account_role()');
select extensions.throws_ok($check$select * from public.admin_registration_organizations()$check$,'42501',null::text,'anon cannot execute admin_registration_organizations()');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'anon cannot execute admin_registration_queue()');
reset role;set local role service_role;
select extensions.throws_ok($check$select * from public.current_account_role()$check$,'42501',null::text,'service_role cannot execute current_account_role()');
select extensions.throws_ok($check$select * from public.admin_registration_organizations()$check$,'42501',null::text,'service_role cannot execute admin_registration_organizations()');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'service_role cannot execute admin_registration_queue()');
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000007","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role() is null,'Pending Client cannot report a privileged active role');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'Pending Client denied sensitive queue');
select extensions.throws_ok($check$select * from public.admin_registration_organizations()$check$,'42501',null::text,'Pending Client denied company choices');
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000003","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role()='staff','Role accessor returns only own stored active role');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'Active Staff denied queue');
select extensions.throws_ok($check$select * from public.admin_registration_organizations()$check$,'42501',null::text,'Active Staff denied choices');
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000002","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role()='admin','Organization Admin role verified');
select extensions.ok((select count(*)=3 from public.admin_registration_queue()),'Organization Admin queue only own assigned requests');
select extensions.ok(not exists(select 1 from public.admin_registration_queue() where email in ('ui-fixture-6@securedesk.example.invalid','ui-fixture-7@securedesk.example.invalid')),'Foreign and unrouted identity details stay hidden');
select extensions.ok((select count(*)=2 from public.admin_registration_organizations() where id::text like 'b2000000-%'),'Company choices include assigned active and pending companies');
select extensions.ok(not exists(select 1 from public.organizations where id='b2000000-0000-4000-8000-000000000002'),'Read-only pending company RPC does not broaden ordinary table RLS');
select extensions.ok((select organization_details->>'address'='UI address 2' from public.admin_registration_queue() where email='ui-fixture-5@securedesk.example.invalid'),'Scoped pending company details accompany request');
select extensions.ok((select not email_confirmed and not can_approve and can_review from public.admin_registration_queue() where email='ui-fixture-8@securedesk.example.invalid'),'Unconfirmed applicant permits review but no approval controls');
select extensions.ok((select count(*)=1 from public.admin_registration_queue('pending',1,0)),'Queue page size applies within tenant');
select extensions.ok((select count(*)=2 from public.admin_registration_queue('pending',10,1)),'Queue offset applies within tenant');
select extensions.ok((select count(*)=0 from public.admin_registration_queue('reviewed')),'Decision history excludes pending requests');
select extensions.ok((select count(*)=1 from public.admin_registration_organizations('company 2')),'Company search is case insensitive and stays scoped');
select extensions.ok((select count(*)=0 from public.admin_registration_organizations('%')),'Search treats wildcard as literal text');
select extensions.throws_ok($check$select * from public.admin_registration_queue('all')$check$,'22023',null::text,'Unknown view rejected');
select extensions.throws_ok($check$select * from public.admin_registration_queue('pending',101,0)$check$,'22023',null::text,'Unbounded page rejected');
select extensions.throws_ok($check$select * from public.admin_registration_queue('pending',10,-1)$check$,'22023',null::text,'Negative offset rejected');
select extensions.throws_ok($check$select * from public.admin_registration_organizations(repeat('x',201))$check$,'22023',null::text,'Oversized search rejected');
reset role; update public.organization_admin_assignments set active=false where organization_id='b2000000-0000-4000-8000-000000000002';
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000002","is_anonymous":false}',true); end $$;
select extensions.ok(not exists(select 1 from public.admin_registration_queue() where email='ui-fixture-5@securedesk.example.invalid'),'Assignment revocation removes queue rows immediately');
select extensions.ok(not exists(select 1 from public.admin_registration_organizations() where id='b2000000-0000-4000-8000-000000000002'),'Assignment revocation removes company choices immediately');
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000001","is_anonymous":false}',true); end $$;
-- Search the fixture namespace: a populated database can exceed the first 100 choices.
select extensions.ok((select count(*)=3 from public.admin_registration_organizations('UI Company') where id::text like 'b2000000-%'),'Super Admin choices include foreign and pending, exclude inactive');
select extensions.ok(exists(select 1 from public.admin_registration_queue('pending',1,(select page_offset from pg_temp.ui_queue_position)) where email='ui-fixture-7@securedesk.example.invalid'),'Super Admin sees unrouted request');
select public.reject_registration_request((select id from public.registration_requests where user_id='b1000000-0000-4000-8000-000000000007'),'Fixture reason');
select extensions.ok(not exists(select 1 from public.admin_registration_queue('pending',1,(select page_offset from pg_temp.ui_queue_position)) where email='ui-fixture-7@securedesk.example.invalid'),'Decision removes request from pending filter before pagination');
select extensions.ok((select status='rejected' and rejection_reason='Fixture reason' and not can_review from public.admin_registration_queue('reviewed') where email='ui-fixture-7@securedesk.example.invalid'),'Reviewed list retains reason and disables controls');
select extensions.throws_ok($check$select app_role from public.profiles$check$,'42501',null::text,'Own role helper does not broaden profile column privileges');
reset role; update auth.users set banned_until=now()+interval '1 day' where id='b1000000-0000-4000-8000-000000000001';
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000001","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role() is null,'Banned Auth actor loses own active role immediately');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'Banned Auth actor denied queue');
reset role; update auth.users set banned_until=null,deleted_at=now() where id='b1000000-0000-4000-8000-000000000001';
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000001","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role() is null,'Deleted Auth actor loses own active role immediately');
select extensions.throws_ok($check$select * from public.admin_registration_organizations()$check$,'42501',null::text,'Deleted actor denied companies');
reset role; update auth.users set deleted_at=null,email_confirmed_at=null where id='b1000000-0000-4000-8000-000000000001';
reset role; set local role authenticated; do $$ begin perform set_config('request.jwt.claim.sub','',true); perform set_config('request.jwt.claims','{"role":"authenticated","sub":"b1000000-0000-4000-8000-000000000001","is_anonymous":false}',true); end $$;
select extensions.ok(public.current_account_role() is null,'Unconfirmed actor loses own active role');
select extensions.throws_ok($check$select * from public.admin_registration_queue()$check$,'42501',null::text,'Unconfirmed actor denied queue');
reset role; select * from extensions.finish();rollback;
